body{font:16px/1.5 system-ui,sans-serif;background:#f3f5f8;color:#182637;margin:0}main{max-width:960px;margin:28px auto;padding:24px;background:#fff;border-radius:12px}h1{font-size:28px}h2{font-size:21px;margin-top:30px}label{display:block;margin:12px 0 4px}input,textarea,button{font:inherit;padding:9px;box-sizing:border-box}input,textarea{max-width:100%;border:1px solid #9ca9ba;border-radius:5px}textarea{width:100%}button{background:#154f82;color:white;border:0;border-radius:5px;cursor:pointer}.error{padding:12px;background:#fff0ee;color:#842c22}.note{background:#edf4fb;padding:12px}.scroll{overflow:auto}table{border-collapse:collapse;min-width:570px;width:100%}th,td{text-align:left;border-bottom:1px solid #ddd;padding:10px}td input{width:130px}small{display:block;color:#526174}form{margin:12px 0}.inline{display:inline-block;margin-right:10px}@media(max-width:600px){main{margin:0;padding:16px;border-radius:0}h1{font-size:24px}}
