<label>Validade da cotação <input type="date" name="quote[valid_until]" min="<?= gmdate('Y-m-d') ?>" value="<?= gmdate('Y-m-d',time()+7*86400) ?>" required></label><label>Tributo percentual <input name="quote[tax_rate]" value="0.00" inputmode="decimal" required></label><label>Observações<textarea name="quote[note]" maxlength="2000" rows="3"></textarea></label><button type="submit">Enviar cotação</button></form><?php } ?>
